package repository

type Book struct {
	ID     int    `json:"id"`
	Title  string `json:"title"`
	Author string `json:"author"`
}

type BookRepository struct {
	books  map[int]Book
	nextID int
}

func NewBookRepository() *BookRepository {
	return &BookRepository{books: make(map[int]Book), nextID: 1}
}

func (r *BookRepository) Add(title, author string) Book {
	b := Book{ID: r.nextID, Title: title, Author: author}
	r.books[b.ID] = b
	r.nextID++
	return b
}

setup_files.handlers/book.go:
package handlers

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"ginapp/repository"
)

func RegisterBookRoutes(r *gin.Engine, repo *repository.BookRepository) {
	r.POST("/books", func(c *gin.Context) {
		var body struct {
			Title  string `json:"title"`
			Author string `json:"author"`
		}
		if err := c.ShouldBindJSON(&body); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusCreated, repo.Add(body.Title, body.Author))
	})
}

