package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func do(t *testing.T, method, path, body string) (int, string) {
	r := SetupRouter()
	var req *http.Request
	if body == "" {
		req = httptest.NewRequest(method, path, nil)
	} else {
		req = httptest.NewRequest(method, path, strings.NewReader(body))
		req.Header.Set("Content-Type", "application/json")
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	return w.Code, w.Body.String()
}

func TestReviewsResource(t *testing.T) {
	r := SetupRouter()

	post := func(body string) map[string]interface{} {
		req := httptest.NewRequest("POST", "/reviews", strings.NewReader(body))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		if w.Code != http.StatusCreated {
			t.Fatalf("POST /reviews: got %d, body %s", w.Code, w.Body.String())
		}
		var m map[string]interface{}
		json.Unmarshal(w.Body.Bytes(), &m)
		return m
	}

	r1 := post(`{"bookId": 7, "text": "great"}`)
	if r1["id"].(float64) != 1 || r1["bookId"].(float64) != 7 || r1["text"] != "great" {
		t.Fatalf("first review wrong: %v", r1)
	}
	post(`{"bookId": 7, "text": "ok"}`)
	post(`{"bookId": 99, "text": "other"}`)

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/reviews?bookId=7", nil))
	if w.Code != http.StatusOK {
		t.Fatalf("GET /reviews: %d", w.Code)
	}
	var list []map[string]interface{}
	json.Unmarshal(w.Body.Bytes(), &list)
	if len(list) != 2 || list[0]["text"] != "great" || list[1]["text"] != "ok" {
		t.Fatalf("reviews for book 7 wrong/ordered: %v", list)
	}
}

func TestBooksStillWork(t *testing.T) {
	code, body := do(t, "POST", "/books", `{"title": "Dune", "author": "H"}`)
	if code != http.StatusCreated {
		t.Fatalf("books route broke: %d %s", code, body)
	}
}

