package repository

type Review struct {
	ID     int    `json:"id"`
	BookID int    `json:"bookId"`
	Text   string `json:"text"`
}

type ReviewRepository struct {
	reviews []Review
	nextID  int
}

func NewReviewRepository() *ReviewRepository {
	return &ReviewRepository{nextID: 1}
}

func (r *ReviewRepository) Add(bookID int, text string) Review {
	rev := Review{ID: r.nextID, BookID: bookID, Text: text}
	r.reviews = append(r.reviews, rev)
	r.nextID++
	return rev
}

func (r *ReviewRepository) ListForBook(bookID int) []Review {
	out := []Review{}
	for _, rev := range r.reviews {
		if rev.BookID == bookID {
			out = append(out, rev)
		}
	}
	return out
}

