package handlers

import (
	"net/http"
	"strconv"

	"github.com/gin-gonic/gin"

	"ginapp/repository"
)

func RegisterReviewRoutes(r *gin.Engine, repo *repository.ReviewRepository) {
	r.POST("/reviews", func(c *gin.Context) {
		var body struct {
			BookID int    `json:"bookId"`
			Text   string `json:"text"`
		}
		if err := c.ShouldBindJSON(&body); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusCreated, repo.Add(body.BookID, body.Text))
	})

	r.GET("/reviews", func(c *gin.Context) {
		bookID, _ := strconv.Atoi(c.Query("bookId"))
		c.JSON(http.StatusOK, repo.ListForBook(bookID))
	})
}

